export declare const TYPESCRIPT_EVALUATOR_SEPARATOR = "---typescript-eval-start---";
export declare const TYPESCRIPT_EVALUATOR_FILE: string;
export declare const PACKAGE_JSON_FILE = "{\n  \"name\": \"e2b-typescript-sandbox\",\n  \"type\": \"module\",\n  \"dependencies\": {\n    \"typescript\": \"latest\"\n  }\n}\n";
export declare const PACKAGE_JSON_FILE_WITH_TSX = "{\n  \"name\": \"e2b-typescript-sandbox\",\n  \"type\": \"module\",\n  \"dependencies\": {\n    \"typescript\": \"latest\",\n    \"tsx\": \"latest\"\n  }\n}\n";
export declare const EXTRACT_IMPORT_NAMES = "import * as ts from \"typescript\";\nimport * as fs from \"fs\";\n\nconst filePath = \"./outputs.ts\";\nconst sourceCode = fs.readFileSync(filePath, \"utf8\");\nconst sourceFile = ts.createSourceFile(filePath, sourceCode, ts.ScriptTarget.Latest, true);\n\nconst npmImports = [];\n\nts.forEachChild(sourceFile, node => {\n  if (ts.isImportDeclaration(node)) {\n    const moduleSpecifier = node.moduleSpecifier;\n    if (ts.isStringLiteral(moduleSpecifier)) {\n      const importPath = moduleSpecifier.text;\n      if (!importPath.startsWith(\".\") && !importPath.startsWith(\"/\")) {\n        const packageName = importPath.replace(/^node:/, \"\");\n        const basePackage = packageName.startsWith(\"@\") \n          ? packageName.split(\"/\").slice(0, 2).join(\"/\")\n          : packageName.split(\"/\")[0];\n        if (!npmImports.includes(basePackage)) {\n          npmImports.push(basePackage);\n        }\n      }\n    }\n  }\n});\n\nconsole.log(npmImports.join(' '));\n";
